/**
 * 收集进度
 * @class LuckySanta_CollectProgress
 */
cc.Class({
    extends: cc.Component,

    properties: {
        percent:0,
        _isCollectState:false,
        
        // progressBar: cc.ProgressBar,
        collectSpr:cc.Node,
        spine_collectSymbol: cc.Node, //收集符号spine
        spine_collectReceiveEff: sp.Skeleton,  //收集时接收特效
        spine_lock: sp.Skeleton,

        spine_progress_complete: sp.Skeleton, //进度完成
        spine_progress_add: sp.Skeleton,  //进度增加
    },

    onLoad() {
        let energyData = cc.vv.gameData.energyData;

        this.setProgress(energyData.needCoins>0?energyData.totalCoin/energyData.needCoins:0);

        this._initListener();
    },

    start() {
        this.showCollect(cc.vv.gameData.isOpenCollectProgress());
    },

    _initListener() {
        Global.btnClickEvent(cc.find("btnUnlock", this.node), this.onBtnUnlockClicked, this);
        Global.btnClickEvent(cc.find("btn_collect_info", this.node), this.onBtnShowInfoClicked, this);

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)
    },

    onBtnUnlockClicked () {
        if (cc.vv.gameData.GetFreeTime() > 0) return;

        if (this.spine_lock.node.active && cc.vv.gameData.GetMaxBetIdx() >= cc.vv.gameData.needBet) {
          cc.vv.gameData.SetBetIdx(cc.vv.gameData.needBet);
            cc.vv.gameData._serverRawMult = cc.vv.gameData.needBet;
            cc.vv.UserManager.setEnterSelectBet(null);
          cc.vv.gameData.GetSlotsScript()._bottomScript.ShowBetCoin();
          //通知押注额修改
          Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, cc.vv.gameData.GetTotalBet());
      }
    },
    
    setBtnsClickEnable (enable) {
        cc.find("btn_collect_info", this.node).getComponent(cc.Button).interactable = enable;
        cc.find("btnUnlock", this.node).getComponent(cc.Button).interactable = enable;
    },

    onEventTotalbetUpdated (event) {
        this.showCollect(cc.vv.gameData.isOpenCollectProgress());
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     * @param percent
     */
    async collectEnergy(globalPosArr, percent) {
        return new Promise(async (success)=> {
            if (globalPosArr.length <= 0) return;

            percent = Math.max(0, Math.min(1, percent));

            Global.SlotsSoundMgr.playEffect("star_fly");

            let endPos = this.spine_collectReceiveEff.node.position;
            let promiseArr = [];
            globalPosArr.forEach(v => {
                let pos = this.node.convertToNodeSpaceAR(v);
                let spine_symbol = cc.instantiate(this.spine_collectSymbol);
                spine_symbol.parent = this.node;
                spine_symbol.position = pos;
                spine_symbol.active = true;

                promiseArr.push(new Promise((res) => {
                    cc.tween(spine_symbol)
                        .call(() => { //播放符号高亮效果
                            spine_symbol.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                            spine_symbol.getComponent(sp.Skeleton).addAnimation(0, "animation2", false);
                        })
                        .delay(0.4)
                        // .call(()=> { //播放飞的效果
                        // })
                        .to(0.5, {/*scale:0.3,*/ position: endPos})
                        .delay(0.5)
                        .call(() => { //播放飞的效果
                            spine_symbol.removeFromParent();
                            res();
                        })
                        .start();
                }));
            });
            await Promise.all(promiseArr);
            this.setProgress(percent);
            Global.SlotsSoundMgr.playEffect("star_collect");

            this.spine_collectReceiveEff.active = true;
            this.spine_collectReceiveEff.setAnimation(0, "animation", false);
            this.spine_collectReceiveEff.setCompleteListener(() => {
                this.spine_collectReceiveEff.active = false;
                this.spine_collectReceiveEff.setCompleteListener(null);
            });

            //收集满
            if (percent == 1) {
                await this.awaitTime(1.0);
            }

            success();
        })
    },

    /**
     * 显示收集界面
     * @param boo
     */
    showCollect(boo) {
        if (this._isCollectState != boo) {
            if(boo) {
                Global.SlotsSoundMgr.playEffect("unlock");

                this.spine_lock.node.active = true;
                this.spine_lock.setAnimation(0, "animation1", false);
                this.spine_lock.setCompleteListener(()=>{
                    this.spine_lock.node.active = false;
                    this.spine_lock.setCompleteListener(null);
                });
            }
            else {
                Global.SlotsSoundMgr.playEffect("lock");

                this.spine_lock.node.active = true;
                this.spine_lock.setAnimation(0, "animation2", false);
                this.spine_lock.setCompleteListener(()=>{
                    this.spine_lock.setAnimation(0, "animation3", false);
                    this.spine_lock.setCompleteListener(null);
                });
            }
        }
        this._isCollectState = boo;
    },

    /**
     * 设置进度
     * @param percent
     */
    setProgress(percent) {
        percent = Math.max(0, Math.min(1, percent));

        if (percent > 0) {


            // this.spine_progress_add.node.x = -this.progressBar.node.width*this.progressBar.node.scaleX*0.5 + this.progressBar.node.width*this.progressBar.node.scaleX*percent;
            this.spine_progress_add.node.active = true;
            this.spine_progress_add.setAnimation(0, "animation", false);
            this.spine_progress_add.setCompleteListener(()=>{
                this.spine_progress_add.node.active = false;
                this.spine_progress_add.setCompleteListener(null);
                this.collectSpr.x = this.collectSpr.width*percent-this.collectSpr.width;

                // this.progressBar.progress = percent;

                if (percent == 1) {
                    Global.SlotsSoundMgr.playEffect("full");

                    this.spine_progress_complete.node.active = true;
                    this.spine_progress_complete.setAnimation(0, "animation", false);
                    this.spine_progress_complete.setCompleteListener(()=>{
                        this.spine_progress_complete.node.active = false;
                        this.spine_progress_complete.setCompleteListener(null);
                    });

                    let infoSpine = cc.find("btn_collect_info/spine", this.node).getComponent(sp.Skeleton);
                    infoSpine.setAnimation(0, "animation2", false);
                    infoSpine.setCompleteListener(()=>{
                        infoSpine.setAnimation(0, "animation1", false);
                        infoSpine.setCompleteListener(null);
                    });
                }
            });
        }
        else {
            this.collectSpr.x = -this.collectSpr.width;
        }
    },

    onBtnShowInfoClicked () {
        Global.SlotsSoundMgr.playEffect("click");
        SlotsFacade.pickGift.enterGame(true);
    },

    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },
});
