// Learn Attribute:
//  - https://docs.cocos.com/creator/manual/en/scripting/reference/attributes.html
// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: cc.Component,

    properties: {
        _enable:false, //当前是否在免费中
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        //隐藏所有子节点
        for (let node of this.node.children) node.active = false;
    },

    start () {
        //断线重连
        if (cc.vv.gameData.isFreeGamesTime() || cc.vv.gameData.isTriggerFreeGames()) {
            if (!(cc.vv.gameData.getDeskInfo().select && cc.vv.gameData.getDeskInfo().select.state == 2)) { //以上条件表示还未选择
                this.ShowFreeGame(true, true);
            }
        }

        // if (cc.vv.gameData.getDeskInfo().freeGameData && cc.vv.gameData.getDeskInfo().freeGameData.state) {
        //     this.ShowFreeGame(true, true);
        // }
    },

    //游戏被选择
    async onSelected () {
        let resp = await cc.vv.gameData.reqSubGame({rtype:2, idx:2});
        if (resp.code === 200) {
            let data = resp.data;

            cc.vv.gameData.SetFreeTime(data.freeCnt);
            cc.vv.gameData.SetTotalFree(data.allFreeCnt);

            await SlotsFacade.popup.showTransition();
            this.ShowFreeGame(true, false);
            SlotsFacade.character.hide();
        }
        else {
            AppLog.err("返回报错了");
        }
    },

    playCollectSilverStar (reels) {
        return new Promise(async (success)=>{
            if (reels) {
                for (let reel of reels) {
                    for (let i=0; i<3; i++) {
                        let symbol = reel.GetSymbolByRow(i);
                        if (symbol.GetShowId() == 14 || symbol.GetShowId() == 15) {
                            symbol.playCoinAppear();
                            await this._awaitTime(1.5);

                            this._starBonus += symbol.GetCoinNum();
                            this.setStarBonus(this._starBonus);
                            await this._awaitTime(0.5);
                        }
                    }
                }
                success();
            }
            else {
                success ();
            }
        });
    },

    bEnable () {
        return this._enable;
    },

    //显示免费
    ShowFreeGame(bFree, bReconnect) {
        this._enable = bFree;

        for (let node of this.node.children) {
            node.active = bFree;
        }

        let collectEnergy = cc.find("Canvas/safe_node/slots/node_energyCollect");
        collectEnergy.active = !bFree;

        this.ShowGameview(bFree);
        cc.vv.gameData.GetSlotsScript()._bottomScript.ShowFreeModel(bFree, cc.vv.gameData.GetTotalFree() - cc.vv.gameData.GetFreeTime(), cc.vv.gameData.GetTotalFree());
        if (bFree) {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("free_bgm");
            SlotsFacade.character.hide();
            this.refreshSpinTimes();

            let gameData = cc.vv.gameData;
            let silvery = gameData.getGameInfo()?gameData.getGameInfo().coinBonus.silvery:gameData.getDeskInfo().coinBonus.silvery;
            this.setEachSilveryStarWinsCoin(silvery || 0);
            this.setEachGoldStarWinsCoin(); //cc.vv.gameData.getDeskInfo().coinBonus.golden 显示Grand

            this._starBonus = bReconnect?cc.vv.gameData.getDeskInfo().starBonus:0;
            this.setStarBonus(this._starBonus, false);

            //显示免费次数
            this.scheduleOnce(()=>{
                Global.SlotsSoundMgr.playEffect("star_added");
                this.ShowGameBottom(bFree);
            }, 1.0);

            //下一局
            this.scheduleOnce(()=>{
                cc.vv.gameData.GetSlotsScript().CanDoNextRound();
            }, 2.0);
        }
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        if(normalFree){ //存在免费游戏背景才执行下面的逻辑
            if(normalBg){
                normalBg.active = !bFree
            }

            normalFree.active = bFree
        }
    },

    ShowGameBottom: function (bFree) {
        if(bFree){
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()

            //显示免费次数
            cc.vv.gameData.GetSlotsScript()._bottomScript.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            cc.vv.gameData.GetSlotsScript()._bottomScript.SetWin(nTotal)
        }
        else{
            cc.vv.gameData.GetSlotsScript()._bottomScript.ShowFreeModel(false)
        }
    },


    refreshSpinTimes () {
        this.setRestSpinTimes(cc.vv.gameData.GetFreeTime() || 0);
    },

    setRestSpinTimes (timesNum) {
        let tips = cc.find("bg/freeTipsBg/tips", this.node);
        let atlas = cc.vv.gameData.GetAtlasByName("bonus");
        if (timesNum > 0) {
            tips.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme129_remaining_text4");
        }
        else if (timesNum == 0) {
            tips.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme129_remaining_text1");
        }
        else if (timesNum < 0) {
            tips.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme129_remaining_text2");
        }

        let lblTimes = cc.find("bg/freeTipsBg/lbTimes", this.node);
        this._setLabel(lblTimes, timesNum>0?timesNum:"");
    },

    setStarBonus (bonusCoin, bAnim=true) {
        let lblBonusCoin = cc.find("starBonus/lblWinCoin", this.node);
        this._setLabel(lblBonusCoin, bonusCoin>0?Global.convertNumToShort(bonusCoin):"");

        if (bonusCoin > 0 && bAnim) {
            Global.SlotsSoundMgr.playEffect("star_value");

            lblBonusCoin.scale = 1.0;
            cc.tween(lblBonusCoin)
                .to(0.3, {scale:1.3})
                .to(0.2, {scale:1.0})
                .start();
        }
    },

    setEachSilveryStarWinsCoin (coinNum) {
        let lblWinCoin = cc.find("bg/item1/lblWinCoin", this.node);
        this._setLabel(lblWinCoin, Global.convertNumToShort(coinNum, null, 2)); //两位小数
    },

    setEachGoldStarWinsCoin (coinNum) {
        let lblWinCoin = cc.find("bg/item2/lblWinCoin", this.node);
        let grand = cc.find("bg/item2/grand", this.node);

        if (coinNum) {
            lblWinCoin.active = true;
            this._setLabel(lblWinCoin, Global.convertNumToShort(coinNum, null, 2)); //两位小数

            grand.active = false;
        }
        else {
            lblWinCoin.active = false;
            grand.active = true;
        }
    },

    //播放Spine
    _playSpine (node, animationName="animation", isLoop=false, endCall=null) {
        return new Promise((success)=>{
            if (node) {
                node.active = true;
                console.log("播放节点[" + node.parent.name + "/" + node.name + "]的spine动作: " + animationName);
                node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
                if (!isLoop) {
                    node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                        if (endCall) endCall();
                        success(); //下一步
                    });
                }
                else {
                    success(); //下一步
                }
            }
            else {
                if (endCall) endCall();
                success(); //下一步
            }
        });
    },

    //播放Actions
    _playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },

    //等待时间
    _awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },

    _setLabel (lblNode, str) {
        if (lblNode) {
            lblNode.getComponent(cc.Label).string = str;
        }
    },

    _cvtToLocalPos (node, localNode) {
        return localNode.convertToNodeSpaceAR(node.parent.convertToWorldSpaceAR(node.position));
    },

});
