cc.Class({
    extends: cc.Component,

    properties: {
        role:sp.Skeleton,
        posGift:cc.Node,
        // wildCnt:80, // 自定义背包75个wild 25+25+25
        _curRoleState:"",
    },

    onLoad() {
        this.setRoleAnimation();
    },

    start() {
    },

    /**
     * 礼物的全局坐标
     * @returns {cc.Vec2}
     */
    getGiftPos() {
        return this.posGift.convertToWorldSpaceAR(cc.v2(0,0));
    },

    /**
     * 播放收集效果
     */
    playCollectGiftEffect() {
        let effect = this.posGift.getChildByName("effect").getComponent(sp.Skeleton);
        effect.node.active = true;
        effect.setAnimation(0, "animation", false);
        effect.setCompleteListener(()=> {
            effect.setCompleteListener(null);
            effect.node.active = false;
        });

        this.setRoleAnimation();
    },

    /**
     * 播放触发pick动画
     */
    triBonusAnim(){
        let tri = this.posGift.getChildByName("tri").getComponent(sp.Skeleton);
        tri.node.active = true;
        tri.setAnimation(0, "animation", false);
        tri.setCompleteListener(()=> {
            tri.setCompleteListener(null);
            tri.node.active = false;
        });
    },

    setRoleAnimation(){
        let totalWildCnt = cc.vv.gameData.totalWildCnt ? cc.vv.gameData.totalWildCnt : 0;
        if(totalWildCnt < 15){
            if(this._curRoleState !== "idle"){
                this.role.setAnimation(0,"idle", true);
            }
            this._curRoleState = "idle"
        } else if(totalWildCnt < 40){
            if(this._curRoleState !== "idle1"){
                this.role.setAnimation(0,"idle1", true);
            }
            this._curRoleState = "idle1"
        } else if(totalWildCnt < 75){
            if(this._curRoleState !== "idle2"){
                this.role.setAnimation(0,"idle2", true);
            }
            this._curRoleState = "idle2"
        } else {
            if(this._curRoleState !== "idle3"){
                this.role.setAnimation(0,"idle3", true);
            }
            this._curRoleState = "idle3"
        }
    },

    show() {
        this.role.node.active = true;
    },

    hide() {
        this.role.node.active = false;
    }
});
