/**
 * 弹窗管理
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _showNode:null,
    },

    /**
     * 显示结算
     * @returns {Promise<void>}
     */
    async showFreegameResultDialog (bFree, winCoin) {
        return new Promise(async (success)=>{
            let free_game_win;
            if(bFree){
                free_game_win = cc.find("uiWinCoinDialouge_o", this.node);
            } else {
                free_game_win = cc.find("uiWinCoinDialouge_h", this.node);
            }
            free_game_win.active = true;

            let ui = free_game_win.getChildByName("uiResult");
            ui.scale = 0;

            ui.getChildByName("lblWinCoin").getComponent(cc.Label).string = "";

            let btnCollect = ui.getChildByName("btn_collect");
            btnCollect.getComponent(cc.Button).enabled = false;

            Global.SlotsSoundMgr.playEffect("normal_dialog_show2");
            await this.playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            Global.SlotsSoundMgr.playEffect("rollNum");
            Global.doRoallNumEff(ui.getChildByName("lblWinCoin"), 0, winCoin,3,null,null,0,true);

            await this.delayTime(2.0);
            btnCollect.getComponent(cc.Button).enabled = true;

            btnCollect.off("click");

            let func = async ()=>{
                btnCollect.getComponent(cc.Button).enabled = false;
                Global.SlotsSoundMgr.playEffect("click");

                Global.SlotsSoundMgr.playEffect("normal_dialog_close");
                await this.playActions(ui, [cc.scaleTo(0.3, 1.8), cc.scaleTo(0.1, 0)]);

                free_game_win.active = false;
                success();
            }

            cc.vv.gameData.checkAutoPlay(btnCollect, func);

            Global.btnClickEvent(btnCollect, async ()=>{
                btnCollect.stopAllActions();
                await func();
            },this);
        });
    },

    /**
     * 显示选择页
     */
    async showStarBonusSelect (eachWinsCoin) {
        return new Promise(async (success)=>{
            let uiSelect = cc.find("uiStarBonusSelect", this.node);
            uiSelect.active = true;

            let ui = uiSelect.getChildByName("ui");
            let btm_info = cc.find("btm_info", ui);

            cc.find("lblWinCoin",btm_info).getComponent(cc.Label).string = Global.convertNumToShort(eachWinsCoin);

            let item1 = cc.find("item1", ui);
            let item2 = cc.find("item2", ui);

            cc.find("spine", item1).active = false;
            cc.find("spine", item2).active = false;

            // cc.find("grayMask", item1).active = false;
            // cc.find("grayMask", item2).active = false;
            Global.showSpriteGray(cc.find("Background", item1), false);
            Global.showSpriteGray(cc.find("text", item1), false);
            Global.showSpriteGray(cc.find("Background", item2), false);
            Global.showSpriteGray(cc.find("text", item2), false);

            Global.SlotsSoundMgr.playEffect("show_dialog");

            //UI淡出
            item1.getComponent(cc.Button).enabled = false;
            item2.getComponent(cc.Button).enabled = false;
            cc.tween(item1)
                .call(()=>{
                    item1.scale=2.0;
                    item1.opacity=0;
                })
                .to(0.2, {scale:1.0, opacity:255})
                .start();
            cc.tween(item2)
                .call(()=>{
                    item2.scale=2.0;
                    item2.opacity=0;
                })
                .delay(0.2)
                .to(0.2, {scale:1.0, opacity:255})
                .start();

            //底部缩放效果
            cc.tween(btm_info)
                .call(()=>{
                    btm_info.scale=2.0;
                    btm_info.opacity=0;
                })
                .delay(0.4)
                .to(0.2, {scale:1.0, opacity:255})
                .start();

            let bg = cc.find("bg", ui);
            bg.opacity = 0;
            await this.playActions(bg, [cc.fadeIn(0.5)]);
            item1.getComponent(cc.Button).enabled = true;
            item2.getComponent(cc.Button).enabled = true;
            this.playSpine(cc.find("spine", item1), null, "animation1", true);
            this.playSpine(cc.find("spine", item2), null, "animation3", true);


            let select_tips = cc.find("select_tips", btm_info);
            select_tips.stopAllActions();
            select_tips.scale = 1.0;
            select_tips.runAction(cc.repeatForever(cc.sequence(
                cc.delayTime(1.0),
                cc.scaleTo(0.2, 1.3),
                cc.scaleTo(0.2, 1.1),
                cc.scaleTo(0.2, 1.3),
                cc.scaleTo(0.2, 1.0),
                )));

            //按钮点击
            item1.off("click");
            Global.btnClickEvent(item1, async ()=>{
                item2.stopAllActions();
                Global.SlotsSoundMgr.playEffect("choose");

                select_tips.stopAllActions();
                item1.getComponent(cc.Button).enabled = false;
                item2.getComponent(cc.Button).enabled = false;

                this.playSpine(cc.find("spine", item1), null, "animation2", false);
                cc.find("spine", item2).active = false;
                // cc.find("grayMask", item2).active = true;
                Global.showSpriteGray(cc.find("Background", item2), true);
                Global.showSpriteGray(cc.find("text", item2), true);

                await this.delayTime(2.3);
                // this.stopSpine(cc.find("spine", item1));

                if (Global.StarBonusRespin) {
                    await Global.StarBonusRespin.onSelected();
                }

                //隐藏
                uiSelect.active = false;

                success();
            },this);



            item2.off("click");
            let func = async ()=>{
                Global.SlotsSoundMgr.playEffect("choose");

                select_tips.stopAllActions();
                item1.getComponent(cc.Button).enabled = false;
                item2.getComponent(cc.Button).enabled = false;

                cc.find("spine", item1).active = false;
                this.playSpine(cc.find("spine", item2), null, "animation4", true);
                // cc.find("grayMask", item1).active = true;

                await this.delayTime(2.3);
                // this.stopSpine(cc.find("spine", item2));

                if (SlotsFacade.bonusFreeGame) {
                    await SlotsFacade.bonusFreeGame.onSelected();
                }

                //隐藏
                uiSelect.active = false;

                success();
            }
            if (cc.vv.gameData.isNeedAutoPlay()) {
                item2.stopAllActions();
                cc.tween(item2)
                    .delay(cc.vv.gameData.getManualAutoPlayTime())
                    .call(()=>{
                        func()
                    })
                    .start();
            }
            Global.btnClickEvent(item2, async ()=>{
                item2.stopAllActions();
                await func();
            },this);

        });
    },

    /**
     * 显示过渡页
     */
    async showTransition () {
        Global.SlotsSoundMgr.playEffect("nudge");
        let spine = cc.find("spine_transition", this.node).getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "skill", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        });
        await SlotsFacade.delayTime(1.2);
    },

    /**
     * 显示过渡页
     */
    async showTransition2 () {
        Global.SlotsSoundMgr.playEffect("nudge");
        let spine = cc.find("spine_transition2", this.node).getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        });
        await SlotsFacade.delayTime(1.8);
    },

    delayTime(time) {
        return new Promise((res, rej) => {
            this.scheduleOnce(()=>{res()}, time);
        });
    },

    playSpine (node, endCall, animationName="animation", isLoop=false) {
        if (node) {
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
            if (!isLoop) {
                node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    if (endCall) endCall();
                });
            }
        }
        else {
            if (endCall) endCall();
        }
    },

    stopSpine (node, track=0) {
        if (node && node.getComponent(sp.Skeleton)) {
            node.getComponent(sp.Skeleton).clearTrack(track);
        }
    },

    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },
});
