let BombItem = function (node, owner) {
    this.node = node;
    this.owner = owner;

    this.jackpotIdx = 0;
    this.spine = cc.find("spine", this.node);

    //恢复初始
    this.resetInit = ()=>{
        this.setJackpotIdx(0); //显示原始bomb
        this.setClickEnable(true);
        // this.setGray(false);
    };

    //设置Idx
    this.setJackpotIdx = (jackpotIdx)=>{
        this.jackpotIdx = jackpotIdx;
        if (jackpotIdx == 0) { //默认
            this.showInit();
        }
    };

    //设置回调
    this.setClickCallback = (callback)=>{
        this.node.off("click");
        Global.btnClickEvent(this.node, ()=>{
            this.setClickEnable(false);
            callback();
        }, this);
    };

    this.setClickEnable = (enabled)=>{
        this.node.getComponent(cc.Button).interactable = enabled;
    };

    this.isClickEnable = ()=>{
        return this.node.getComponent(cc.Button).interactable;
    };

    //设置为灰色
    // this.setGray = (isGray)=>{
    //     let color = isGray?new cc.Color(80,80,80,255):cc.Color.WHITE;
    //     for (let node of this.node.children) {
    //         node.color = color;
    //     }
    // };

    //显示初始
    this.showInit = ()=>{
        this.node.zIndex = 0;
        this.showChooseTips();
    };

    //资源是1grand2major3minor4mini
    //定义Jackpot是 1mini2minor3major4grand
    this.getResId = (jackpotId)=>{
        return 5 - jackpotId;
    };

    //显示点击提示
    this.showChooseTips = ()=>{
        this.owner.playSpine(this.spine, "animation05", true);
    };

    //显示爆开
    this.showBombing = ()=>{
        this.owner.playSpine(this.spine, "animation0" + this.getResId(this.jackpotIdx), false, ()=>{
            this.showResult();
        });
    };

    //显示结果
    this.showResult = ()=>{
        this.owner.playSpine(this.spine, "animation0" + this.getResId(this.jackpotIdx) + "_1");
    };

    //显示中奖
    this.showWin = ()=>{
        this.node.zIndex = 2;
        this.owner.playSpine(this.spine, "animation0" + this.getResId(this.jackpotIdx) + "_2", true);
    };

};

cc.Class({
    extends: cc.Component,

    properties: {
        _uiMain: null,
        _uiResult: null,

        _itemsList: null,

        _subgameInfo: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._soundCfg = cc.vv.gameData.getGameCfg().soundCfg;

        this._uiResult = cc.find("uiResult", this.node);
        this._uiResult.active = false;

        this._uiMain = cc.find("uiMain", this.node);
        this._uiMain.active = false;

        cc.find("LMSlots_PrizePool_1", this._uiMain).addComponent("LMSlots_PrizePool_Base");

        this._grayLayer = cc.find("itemListBg/List/grayLayer", this._uiMain);

        this._itemsList = [];

        let listNode = cc.find("itemListBg/List", this._uiMain);
        let itemTemplate = cc.find("ItemTemplate", listNode);
        itemTemplate.active = false;
        for (let i=0; i<12; i++) {
            let item = cc.instantiate(itemTemplate);
            item.active = true;
            item.name = i.toString();
            item.parent = listNode;
            this._itemsList.push(new BombItem(item, this));
        }

        //先初始化
        this._resetInit();
    },

    async enterGame (subgameInfo, isReconnected=false) {
        this._subgameInfo = subgameInfo;

        cc.vv.gameData.GetSlotsScript()._bottomScript.ShowBtnsByState("moveing_1");
        Global.SlotsSoundMgr.playBgm("pick_bgm");

        //先初始化
        this._resetInit();
        //设置奖池，不让动
        this._lockJackpot(this._subgameInfo.jackpot || [0,0,0,0]);

        //显示游戏主界面
        await this._showMain(isReconnected);
        //显示结算界面
        await this._showResultDialouge(this._subgameInfo.wincoin, this._subgameInfo.jackpotId);
        //退出游戏
        await this.exitGame();
    },

    async exitGame () {
        //过渡界面
        await this._playTransition();
        this.scheduleOnce(()=>{
            //先初始化
            this._resetInit(false);
        }, 0.5);
        // 可以操作
        cc.vv.gameData.GetSlotsScript()._bottomScript.ShowBtnsByState("idle");

        Global.SlotsSoundMgr.stopBgm();
    },

    start () {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        if (deskInfo.christmas && deskInfo.christmas.state) { //断线重连
            this.scheduleOnce(()=>{
                this.enterGame(deskInfo.christmas, true);
            }, 0.2); //留点时间初始化其他项
            cc.vv.gameData.GetSlotsScript()._topScript.SetBackLobby(false);
        }
    },

    //恢复初始化
    _resetInit (hideTranstion=true) {
        for (let subNode of this.node.children) {
            if ((subNode.name == "spine_transition" || subNode.name == "spine_transition2") && !hideTranstion) { //防止结束的时候，过渡场景被隐藏
                continue;
            }
            else {
                subNode.active = false;
            }
        }
        for (let item of this._itemsList) item.resetInit();

        this._setGrayLayerVisible(false);
        //屏蔽其他物品点击
        this._setUnSelectItemsClickEnable(true);
    },

    _restoreByServerData () {
        //恢复选项
        let choice = this._subgameInfo.choice || [];
        for (let i=0; i<this._itemsList.length; i++) {
            let jackpotid = choice[i];

            let bombItem = this._itemsList[i];
            bombItem.setJackpotIdx(choice[i]);

            if (jackpotid > 0) {
                bombItem.showResult();
            }
        }

        //屏蔽其他物品点击
        this._setUnSelectItemsClickEnable(true);
    },

    //显示游戏主界面
    async _showMain(isReconnected) {
        this.scheduleOnce(()=>{
            this._uiMain.active = true;
            if (isReconnected) {
                //根据数据恢复场景
                this._restoreByServerData();
            }
        }, 0.5);
        //过渡界面
        await this._playTransition();

        return new Promise(async (success, failed)=>{

            let self = this;
            let func = async (bombItem)=>{
                Global.SlotsSoundMgr.playEffect("pick");
                for (let bombItem of this._itemsList){
                    bombItem.node.stopAllActions();
                }

                    //屏蔽其他物品点击
                self._setUnSelectItemsClickEnable(false);

                let idx = parseInt(bombItem.node.name);
                let resp = await cc.vv.gameData.reqSubGame({rtype:1, idx:idx + 1});
                if (resp.code === 200) {
                    let info = resp.data;
                    // self._subgameInfo = info;

                    bombItem.setJackpotIdx(info.choice[idx]);
                    //播放爆炸效果
                    bombItem.showBombing();
                    await self.awaitTime(1.0);

                    if (info.wincoin > 0) {
                        self._subgameInfo.wincoin = info.wincoin;
                        self._subgameInfo.choice = info.choice;
                        self._subgameInfo.jackpotId = info.jackpotId;

                        //播放中奖结果
                        self._playWinEffect(info.jackpotId, info.choice);
                        await self.awaitTime(3.0);

                        Global.SlotsSoundMgr.playEffect("pick_end");

                        cc.vv.gameData.AddCoin(info.wincoin);
                        let _topScript = cc.vv.gameData.GetSlotsScript()._topScript;
                        _topScript.ShowCoin();

                        //下一步，结算。。。
                        success();
                    }
                    else {
                        //设置其他未选择的继续操作
                        self._setUnSelectItemsClickEnable(true);
                        autoClick();
                    }
                }
                else {
                    console.log("返回数据错误!");
                    failed();
                }
            }

            let autoClick = function () {
                let list = [];
                self._itemsList.forEach(item=>{
                    if(item.jackpotIdx == 0){
                        list.push(item);
                    }
                })
                let bombItem = list[Global.random(0,list.length-1)];
                cc.vv.gameData.checkAutoPlay(bombItem.node, function () {
                    func(bombItem);
                })
            }

            autoClick();
            //操作Item
            for (let bombItem of this._itemsList) {
                bombItem.setClickCallback(async ()=>{
                    func(bombItem);
                });
            }
        });
    },

    //设置是否可以点击
    _setUnSelectItemsClickEnable (enable) {
        for (let bombItem of this._itemsList) {
            if (bombItem.jackpotIdx == 0) {
                bombItem.setClickEnable(enable);
                bombItem.showChooseTips();
            }
            // else {
            //     bombItem.setClickEnable(!enable);
            // }
        }
    },

    //显示未选中Items
    _showUnchooseResult (winJackpotId, choice) {
        for (let bombItem of this._itemsList) {
            if (bombItem.jackpotIdx == 0) {
                let idx = parseInt(bombItem.node.name);
                bombItem.setJackpotIdx(choice[idx]);
                bombItem.showBombing();
            }
        }
    },

    _setGrayLayerVisible (isVisible) {
        this._grayLayer.active = isVisible;
        if (isVisible) {
            let listNode = cc.find("itemListBg/List", this._uiMain);
            listNode.getComponent(cc.Layout).enabled = false;

            this._grayLayer.width = cc.find("Canvas").width;
            this._grayLayer.height = cc.find("Canvas").height;

            this._grayLayer.position = this._grayLayer.parent.convertToNodeSpaceAR(cc.find("Canvas").convertToWorldSpaceAR(cc.v2(0,0)));
            this._grayLayer.zIndex = 1;
        }
    },

    //播放中奖结果
    _playWinEffect(winJackpotId, choice) {
        let listNode = cc.find("itemListBg/List", this._uiMain);
        listNode.getComponent(cc.Layout).enabled = false;

        //显示灰色层
        this._setGrayLayerVisible(true);
        //播放中奖特效
        this._playJackpotWinEffect(winJackpotId);
        //未选择的显示结果
        this.scheduleOnce(()=>{
            this._showUnchooseResult(winJackpotId, choice);
        }, 0.8);
    },

    //播放奖池中奖特效
    _playJackpotWinEffect(winPropIdx) {
        Global.SlotsSoundMgr.playEffect("bell");
        Global.SlotsSoundMgr.playEffect("pick_hit");

        for (let bombItem of this._itemsList) {
            if (bombItem.jackpotIdx == winPropIdx) { //实际是应该等于中奖物品
                bombItem.showWin();
            }
        }
    },

    _convertNodePosToLocalPos (node, localNode) {
        return localNode.convertToNodeSpaceAR(node.parent.convertToWorldSpaceAR(node.position));
    },

    //过渡界面
    async _playTransition() {
        Global.SlotsSoundMgr.playEffect("transition1");

        let spine_transition = cc.find("spine_transition", this.node);
        await this.playSpine(spine_transition);
        spine_transition.active = false;
    },

    //显示结算界面
    async _showResultDialouge(winCoin, winJackpotId) {
        let frameName = ["theme129_popup_text11", "theme129_popup_text12", "theme129_popup_text10", "theme129_popup_text9"];
        //更新所中奖池Sprite
        let jackpot_txt = cc.find("jackpot_txt", this._uiResult).getComponent(cc.Sprite);
        jackpot_txt.spriteFrame = cc.vv.gameData.GetAtlasByName("dialog").getSpriteFrame(frameName[winJackpotId - 1]);

        //更新winCoin
        let twinCoin = winCoin;
        let winCoinStr = Global.formatMoney(twinCoin);
        let num = 0;
        while (winCoinStr.length > 10) {
            twinCoin = Math.floor(twinCoin/1000);
            winCoinStr = Global.formatMoney(twinCoin);
            num ++;
        }
        let unit = ["", "K", "M", "B", "T", "Q"];
        winCoinStr += unit[num];

        let lblWinCoin = cc.find("lblWinCoin", this._uiResult).getComponent(cc.Label);
        lblWinCoin.string = winCoinStr;

        //出现效果
        this._uiResult.active = true;
        this._uiResult.opacity = 0;
        await this.playActions(this._uiResult, [cc.fadeIn(0.5)]);
        await this.awaitTime(1.0);

        //显示bigwin
        await this.showBottomWin(winCoin);

        await this.awaitTime(0.5);
    },

    async showBottomWin (winCoin) {
        return new Promise((success)=>{
            cc.vv.gameData.GetSlotsScript().ShowBottomWin(winCoin,winCoin,true, ()=>{
                success();
            });
        });
    },

    //奖池锁定(停止滚动)
    _lockJackpot(jackpotList){
        let prizepool = cc.find("LMSlots_PrizePool_1", this._uiMain).getComponent("LMSlots_PrizePool_Base");
        prizepool.PausePool([{prizeType:0,pauseNum:jackpotList[0]},{prizeType:1,pauseNum:jackpotList[1]},
            {prizeType:2,pauseNum:jackpotList[2]},{prizeType:3,pauseNum:jackpotList[3]}]);
    },

    //播放Spine
    playSpine (node, animationName="animation", isLoop=false, endCall=null) {
        return new Promise((success)=>{
            if (node) {
                node.active = true;
                console.log("播放节点[" + node.parent.name + "/" + node.name + "]的spine动作: " + animationName);
                node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
                if (!isLoop) {
                    node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                        if (endCall) endCall();
                        success(); //下一步
                    });
                }
                else {
                    success(); //下一步
                }
            }
            else {
                if (endCall) endCall();
                success(); //下一步
            }
        });
    },

    //播放Actions
    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },

    //等待时间
    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },
});
