/**墨西哥帅哥-符号表
 *
 */
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {

    },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById:function(id,data, bRolling=true){
        this._super(id,data);

        let cfg = cc.vv.gameData.getGameCfg()
        cc.find("mask", this.node).active = false
        if (Global.StarBonusRespin && Global.StarBonusRespin.bEnable() && bRolling) {
            if(cfg.symbol[id] && cfg.symbol[id].dark){
                cc.find("mask", this.node).active = true
            }
        }

        if (this._id == 2) { //星星
            let num = 0;
            if (this._data && this._data.t == "coin")  {
                num = this._data.num;
            }
            else {
                num = Math.floor(cc.vv.gameData.GetTotalBet()*(Global.random(1, 10)/2));
            }
            this.SetCoinNum(Global.convertNumToShort(num, null, 2));
        }
        else {
            this.SetCoinNum(null);
        }
    },

    //显示正常的结果图标
    ShowNormal:function(){
        this.ShowById(this._id,this._data)
        this.setAnimationToTop(false)
    },

    //开始旋转时刻
    StartMove:function(){
        this.setAnimationToTop(false)
        this.ShowKuang(false)
        this.stopWinTweenAction()
        this.node.zIndex = 50 - this._symbolIdx  + this._reelIdx*10;
    },

    //显示随机符号
    ShowRandomSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbols.length)
        let randVal = cfg.randomSymbols[randIdx-1]
        if (Global.StarBonusRespin && Global.StarBonusRespin.bEnable()) {
            randIdx = Global.random(1,cfg.respinRandomSymbols.length)
            randVal = cfg.respinRandomSymbols[randIdx-1]
        }
        this.ShowById(randVal)
    },

    GetCoinNum: function () {
        return this._data?this._data.num:0;
    },

    SetCoinNum:function(num) {
        let txt = cc.find("coin_num",this.node);
        if(num){
            txt.scale = 1;
            txt.active = true;
            txt.getComponent(cc.Label).string = Global.formatMoney(num);
        }
        else{
            txt.active = false
        }
    },

    playCoinAppear:function (bScale=true) {
        this.SetCoinNum(Global.convertNumToShort(this._data?this._data.num:0, null, 2));

        let txt = cc.find("coin_num",this.node);

        if (bScale) {
            txt.scale = 0;
            cc.tween(txt)
                .call(()=>{
                    this.playAppearAnimation();
                })
                .delay(0.8)
                .to(0.3, {scale:1.2})
                .to(0.3, {scale:1.0})
                .start();
        }
        else {
            txt.scale = 1.0;
            this.playAppearAnimation();
        }
    },

    //播放出现动画
    playAppearAnimation(bCzIndex = true){
        let id = this._id

        if (id == 14 || id == 15) { //白银星星 黄金星星
            let cfg = cc.vv.gameData.getGameCfg()
            if(cfg.symbol[id] && cfg.symbol[id].appear_ani){
                let showNode = cc.find(cfg.symbol[id].appear_ani.node,this.node);
                showNode.active = true;

                if(cfg.symbol[id].appear_ani.name != ""){
                    if(bCzIndex){
                        this.node.zIndex = cfg.symbol[id].appear_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                    }
                    let nodeSp = showNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0,cfg.symbol[id].appear_ani.name,false);
                        nodeSp.setCompleteListener(()=>{
                            showNode.active = false;
                            nodeSp.setCompleteListener(null);
                        });
                    }
                }
            }
        }
    },

    //停止动画
    playStopAnimation(){
        let id = this._id

        if (id == 14 || id == 15) { //白银星星 黄金星星
            let cfg = cc.vv.gameData.getGameCfg()
            if(cfg.symbol[id] && cfg.symbol[id].stop_ext_ani){
                this._state = "stop";
                let showNode = cc.find(cfg.symbol[id].stop_ext_ani.node,this.node);
                showNode.active = true;

                if(cfg.symbol[id].stop_ext_ani.name != ""){
                    this.node.zIndex = cfg.symbol[id].stop_ext_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                    let nodeSp = showNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0,cfg.symbol[id].stop_ext_ani.name,false);
                        nodeSp.setCompleteListener(()=>{
                            showNode.active = false;
                            nodeSp.setCompleteListener(null);
                        });
                    }
                }
            }
        }
        else {
            if (!(Global.StarBonusRespin && Global.StarBonusRespin.bEnable())) {
                this._super();
            }
        }
    },

    //赢钱动画
    playStarAnimation(){
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg();

        if (id == cfg.collectId) {
            if(cfg.symbol[id] && cfg.symbol[id].win_node){
                this._state = "win";
                if(this._showNode){
                    this._showNode.active = false
                }
                let aniNode = this.setAnimationToTop(true)
                aniNode.active = true
                let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
                topShowNode.active = true
                if(cfg.symbol[id].win_ani && cfg.symbol[id].win_ani.name != ""){
                    aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                    let nodeSp = topShowNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0,cfg.symbol[id].win_ani.name, false)
                    }
                }
            }
        }
    },

    //播放win效果但又没有spin动画。自己写一个tween的action
    //先填写个默认的。
    // playWinTweenAction(){
    //     this._showNode.cleanup()
    //     //记录原始缩放
    //     let nOpacity = this._showNode.opacity;
    //     this._showNodeOrgOpacity = nOpacity
    //
    //     cc.tween(this._showNode)
    //         .repeatForever(cc.tween()
    //             .to(0.1,{opacity:0})
    //             .delay(0.6)
    //             .to(0.2,{opacity:nOpacity})
    //             .delay(0.2)
    //         )
    //         .start()
    // },
});
