let BOX_NUM = 26;
let MULT_ARR = [
    2,3,4,5,6,7,8,9,10,12,15,20,30,
    50,60,70,80,90,100,150,200,300,500,750,1000,1500
];

let TitleType = {
    GOOD_LUCK:1,
    CHOOSE_GIFT:2,
    SELECT_TIMES:3,
};

let GameState = {
    COLLECTING:0, //收集中...
    FIRST_CHOOSE:1, //第一次选择
    CHOOSEING:2,  //选择中
    ROUND_END:3,    //一轮结束
    LAST_CHOOSE:4,  //最后一次选择
};

let MULT_COLOR = {
    GREEN:"green",
    RED:"red",
    GRAY:"gray",
};


let MultItem = function (node, owner) {
    this.node = node;
    this._owner = owner;
    this._color = MULT_COLOR.GREEN;

    //初始化
    this.init = function() {
        //隐藏所有子节点
        cc.find("spine", this.node).active = false;

        //设置背景颜色
        let id = parseInt(this.node.name);
        this.setColor(id < 13?MULT_COLOR.GREEN:MULT_COLOR.RED);
    };

    //设置倍数
    this.setMult = function(mult) {
        let lblMult = cc.find("lblMult", this.node);
        lblMult.active = true;
        this._owner._setLabel(lblMult, mult);
    };

    //变颜色ToGray
    this.playToGray = function() {
        let spineNode = cc.find("spine", this.node);
        this._owner._playSpine(spineNode,"animation", false, ()=>{
            this.setColor(MULT_COLOR.GRAY);
            spineNode.active = false;
        });
    };

    //设置颜色
    this.setColor = function(color) {
        this._color = color;
        this._refreshColor();
    };

    //刷新颜色
    this._refreshColor = function()  {
        for (let key in MULT_COLOR) {
            cc.find(MULT_COLOR[key], this.node).active = false;
        }
        cc.find(this._color, this.node).active = true;
    };
};


let BoxItem = function (node, owner) {
    this.node = node;
    this._owner = owner;
    this._idNum = 0;
    this._spine_light = cc.find("spine_light", this.node);

    //初始化
    this.init = function()  {
        //隐藏所有子节点
        for (let sbd of this.node.children) sbd.active = false;
        //显示Box
        cc.find("box", this.node).active = true;
        //显示标签
        this._idNum = parseInt(this.node.name) + 1;
        this._owner._setLabel(cc.find("box/lblIdxNum", this.node), this._idNum);
    };

    //设置回调
    this.setClickCallback = function(callback) {
        this.node.off("click");
        Global.btnClickEvent(this.node, ()=>{
            this.setClickEnable(false);
            callback();
        }, this);
    };

    //设置点击与否
    this.setClickEnable = function(enabled) {
        this.node.getComponent(cc.Button).interactable = enabled;
    };

    //是否可点
    this.isClickEnable = function() {
        return this.node.getComponent(cc.Button).interactable;
    };

    //获取Id
    this.getId = function() {
        return this._idNum;
    };

    //播放出现特效
    this.playAppearEff = function() {
        this.node.active = true;
        let box = cc.find("box", this.node);
        box.scale = 0;

        //出现spine特效
        let spine_comming_node = cc.find("spine_coming", this.node);
        this._owner._playSpine(spine_comming_node, "animation", false, ()=>{
            spine_comming_node.active = false;
        });

        //缩放特效
        cc.tween(box)
            .to(0.3, {scale:0.35})
            .to(0.1, {scale:0.19})
            .start();
    };

    this.playDisappear = function() {
        this.init();
        this.node.active = false;
    };

    //播放显示粉色描边
    this.playPinkStroke = function() {
        this._owner._playSpine(this._spine_light, "animation1", false, ()=>{
            this._owner._playSpine(this._spine_light, "animation2");
        });
    };

    this.hasStrokeEff = function () {
       return this._spine_light.active;
    };

    this.removeStrokeEff = function () {
        this._spine_light.active = false;
    };

    //播放飞到Your Gift
    this.flyToYourGift = function (startPos, targetPos) {
        Global.SlotsSoundMgr.playEffect("gift_fly");

        this._playParticleEff(true);
        this._playWhiteStroke(()=>{
            Global.SlotsSoundMgr.playEffect("gift_out1");
            cc.tween(this.node)
                .to(0.5, {position:targetPos, scale:1.68})
                .call(()=>{
                    //停止拖尾粒子
                    this._playParticleEff(false);
                    //隐藏描边
                    this.removeStrokeEff();
                })
                .start();
        });
    };

    //播放显示白色描边
    this._playWhiteStroke = function (callback) {
        this._owner._playSpine(this._spine_light, "animation3", false, ()=>{
            this._owner._playSpine(this._spine_light, "animation4");
            if (callback) {
                callback();
            }
        });
    };

    //播放拖尾粒子效果
    this._playParticleEff = function (bAnim) {
        let tuoweiPtcl = cc.find("tuoweiPtcl", this.node);
        tuoweiPtcl.active = bAnim;

        if (bAnim) {
            let ptcl = tuoweiPtcl.getComponent(cc.ParticleSystem);
            ptcl.resetSystem();
        }
    };
};



cc.Class({
    extends: cc.Component,

    properties: {
        _isLook: false,

        _uiMain: null,
        _uiBg1: null, //未集满显示的背景内容
        _uiBg2: null, //集满开始游戏时的背景内容

        _yourGiftBoxItem: null,  //你的box

        _multItemsList: null,
        _boxItemsList: null,
        _giveMultLblList: null,

        _freeBags: null,

        _multConf: null, //倍数配置
        _totalRound: 0,  //总共轮数
        _currRound:null, //已经抽取的轮
        _currCount: 0,  //当前收集bags个数

        _historyMult:null, //已放弃的倍数
        _gainMult:null, //当前要开奖的倍数
        _prize:null,  //奖杯收集满之后，可计算出平均价值
        _hasChoices:null, //存储客户端已选择的位置
        _unpickedMult:null, //剩余可抽的倍数

        _state:null,
        _nextRound:null,//状态是2的情况下，记录接下来是那一轮
        _nextChooseCount:null, //状态是2的情况下，记录接下来选择几个奖杯
        _options:null, //状态是4的情况下，最终选择的奖杯序号
        _lastChoice:null,

        _curRoundPickBoxList: null, //当前轮选择个数
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._initData();

        this._uiMain = cc.find("uiMain", this.node);

        this._uiBg1 = cc.find("uiBg1", this._uiMain);

        this._uiBg2 = cc.find("uiBg2", this._uiMain);
        cc.find("box_pos", this._uiBg2).active = false;

        let multListNode = cc.find("multList", this._uiMain);
        for (let subNode of multListNode.children) subNode.active = false;

        this._multItemsList = [];
        for (let i=0; i<BOX_NUM; i++) {
            let item = cc.instantiate(cc.find("ItemTemplate", multListNode));
            item.name = i.toString();
            item.active = true;
            item.position = cc.find("Item" + (i + 1), multListNode).position;
            item.parent = multListNode;

            let multItem = new MultItem(item, this);
            multItem.init();
            multItem.setMult(this._multConf[i]);
            multItem.setColor(MULT_COLOR.GREEN);

            this._multItemsList.push(multItem);
        }

        let boxListNode = cc.find("boxList", this._uiMain);
        for (let subNode of boxListNode.children) subNode.active = false;

        this._boxItemsList = [];
        for (let i=0; i<BOX_NUM; i++) {
            let item = cc.instantiate(cc.find("ItemTemplate", boxListNode));
            item.name = i.toString();
            item.active = true;
            item.position = cc.find("Item" + (i + 1), boxListNode).position;
            item.parent = boxListNode;

            let boxItem = new BoxItem(item, this);
            boxItem.init();

            this._boxItemsList.push(boxItem);
        }

        this._giveMultLblList = [];
        for (let i=1; i<=5; i++) {
            this._giveMultLblList.push(cc.find("giveupMultList/lblMult" + i, this._uiBg2));
        }

        //隐藏所有子节点
        for (let subnode of this.node.children) subnode.active = false;
    },

    start () {
        //断线重连
        // if (cc.vv.gameData.getDeskInfo().select && cc.vv.gameData.getDeskInfo().select.state == 3) {
        //     this.enterGame();
        // }
    },

    //进入游戏
    //isLook 查看
    async enterGame (isLook=false) {
        this._isLook = isLook;

        if (!isLook) Global.SlotsSoundMgr.playBgm("deal_bgm");

        //屏蔽操作
        cc.vv.gameData.GetSlotsScript()._bottomScript.ShowBtnsByState("moveing_1");

        //显示主页面
        await this._showMain();
        //退出游戏
        await this.exitGame();
    },

    //退出游戏
    async exitGame () {
        //隐退
        await this._disappearFadeOut();

        //清空数据
        this._freeBags = null;

        //恢复操作
        cc.vv.gameData.GetSlotsScript()._bottomScript.ShowBtnsByState("idle");

        Global.SlotsSoundMgr.stopBgm();
    },

    //初始化
    _onInit () {
        this._uiBg1.active = true;
        this._uiBg2.active = false;

        for (let multItem of this._multItemsList) {
            multItem.init();
        }

        for (let boxItem of this._boxItemsList) {
            boxItem.init();
            boxItem.node.active = false;
        }

        for (let lbl of this._giveMultLblList) {
            this._setLabel(lbl, "");
        }

        cc.find("clickMaskTouch", this._uiMain).active = false;

        //显示标题
        this._setTitleType(TitleType.GOOD_LUCK);
        //设置不可点
        this._setAllBoxItemsClickEnable(false);
        //bg2粒子隐藏
        cc.find("xiangshangParticle", this._uiBg2).active = false;
    },

    //数据初始化
    //主要是对数据进行处理，赋值到变量，状态等
    _initData () {
        if (!this._freeBags) {
            this._freeBags = cc.vv.gameData.getGameInfo()?cc.vv.gameData.getGameInfo().freeBags:cc.vv.gameData.getDeskInfo().freeBags;
        }

        this._multConf = this._freeBags.conf || MULT_ARR;
        this._currCount = this._freeBags.currCnt; //当前个数

        this._totalRound = 5; //固定5轮
        this._currRound = this._freeBags.picked;  //已经抽取的轮
        this._unpickedMult = this._freeBags.unpickedMult; //剩余可抽的倍数

        this._historyMult = this._freeBags.historyMult; //已放弃的倍数
        this._gainMult = this._freeBags.mult; //当前要开奖的倍数
        this._prize = this._freeBags.prize;  //奖杯收集满之后，可计算出平均价值
        this._hasChoices = this._freeBags.choices; //存储客户端已选择的位置

        let curState = this._freeBags.currState;
        this._state = curState.state || 0;
        this._nextRound = curState.nextRound;  //状态是2的情况下，记录接下来是那一轮
        this._nextChooseCount = curState.nextCount;  //状态是2的情况下，记录接下来选择几个奖杯
        this._options = curState.options; //状态是4的情况下，最终选择的奖杯序号

        this._lastChoice = this._freeBags.lastChoice;
    },

    //根据数据恢复--断线重连
    _restoreByServerData () {
        //显示是否收集模式
        this._showModule(this._state == GameState.COLLECTING);
        //显示已收集礼包
        let count = this._currCount;
        if (!this._isLook && (this._state == GameState.COLLECTING || this._state == GameState.FIRST_CHOOSE)) { //最后一个需要播放收集效果
            count = this._currCount - 1;
        }
        for (let i=0; i<this._currCount; i++) {
            this._boxItemsList[i].node.active = true;
        }

        //去掉已经选择的
        for (let idx of this._hasChoices) {
            this._boxItemsList[idx - 1].node.active = false;
        }

        //显示已放弃倍数
        for (let i in this._historyMult) {
            this._setLabel(this._giveMultLblList[i], this._historyMult[i]+"X");
        }
        //显示剩余可抽倍数
        //全部变灰
        for (let multItem of this._multItemsList)  {
            multItem.setColor(MULT_COLOR.GRAY);
            multItem.node.opacity = this._state == GameState.COLLECTING?150:255;
        }
        //根据数据把剩余的显示亮
        for (let unpickmult of this._unpickedMult) {
            this._multItemsList[this._getIdxByMult(unpickmult)].init();
        }
    },

    //显示主要内容
    async _showMain () {
        this._uiMain.active = true;

        return new Promise(async (success, error)=>{
            //初始化
            this._onInit();
            //初始化数据
            this._freeBags = null; //赋值为空，为了取到最新数据，而不是DeskInfo里的数据
            this._initData();
            //断线重连
            this._restoreByServerData();
            //隐现
            await this._appearFadeIn();

            //查看模式
            if (this._isLook) {
                let clickMask = cc.find("clickMaskTouch", this._uiMain);
                clickMask.active = true;
                Global.btnClickEvent(clickMask,()=>{
                    clickMask.active = false;

                    Global.SlotsSoundMgr.playEffect("click");

                    success();
                });
            }
            else {
                if (!this._isLook && this._state == GameState.COLLECTING) {
                    Global.SlotsSoundMgr.playEffect("deal_scene_open");
                    await this._playCollecGiftBoxEff();
                    //显示1秒
                    await this._awaitTime(1.0);
                    SlotsFacade.collectProgress.setProgress(0);
                    success();
                }
                else {
                    //非查看模式
                    if (!this._isLook && this._state == GameState.FIRST_CHOOSE) { //最后一个需要播放收集效果
                        Global.SlotsSoundMgr.playEffect("full");
                        await this._playCollecGiftBoxEff();
                    }

                    //显示开始
                    if (this._state == GameState.FIRST_CHOOSE) {
                        //全部变灰
                        for (let multItem of this._multItemsList)  {
                            multItem.node.opacity = 255;
                        }


                        console.log("第一次选择",this._currRound,this._totalRound);
                        this._showModule(false);
                        //弹出开始
                        await this.popUIStartTips();
                        //选择你的Box
                        await this._chooseYourBox();

                        console.log("第一次选择---结束",this._currRound,this._totalRound);
                    }

                    //循环轮数
                    while (this._currRound < this._totalRound) {
                        //选择一轮
                        if (this._state == GameState.CHOOSEING) {
                            console.log("选择一轮开始",this._currRound,this._totalRound);
                            if (!this._yourGiftBoxItem) {
                                this._showYourBox(this._boxItemsList[this._lastChoice[0] - 1], false);
                            }
                            //显示标题
                            this._setTitleType(TitleType.GOOD_LUCK);
                            //轮数提示
                            await this.popUIRoundTips(this._nextRound, this._nextChooseCount);
                            //显示标题
                            this._setTitleType(TitleType.SELECT_TIMES, this._nextChooseCount);
                            //选择box
                            await this._chooseCurRoundBox(this._nextChooseCount);
                            console.log("选择一轮结束",this._currRound,this._totalRound);
                        }

                        //一轮结算
                        if (this._state == GameState.ROUND_END) {
                            console.log("一轮结算",this._currRound,this._totalRound);
                            let bFinish = await this.popUIRoundResultTips();
                            if (bFinish) break;
                        }
                    }

                    //最后的选择
                    if (this._state == GameState.LAST_CHOOSE) {
                        await this.popUILastRoundSelectTip(this._lastChoice[0], this._lastChoice[1]);
                    }

                    console.log("大结算",this._currRound,this._totalRound);
                    //显示结算
                    await this.popUIEndResultTips();

                    //显示1秒
                    await this._awaitTime(1.0);

                    SlotsFacade.collectProgress.setProgress(0);
                    success();
                }
            }
        });
    },

    //通过倍数获取Idx
    _getIdxByMult (fMult) {
        for (let i in this._multConf) {
            let mult = this._multConf[i];
            if (mult == fMult) {
                return i;
            }
        }
    },

    //选择你的Box
    _chooseYourBox () {
        return new Promise(async (success)=>{
            //全部设置成可点
            this._setAllBoxItemsClickEnable(true);

            for (let boxItem of this._boxItemsList) {
                boxItem.setClickCallback(async ()=>{
                    //全部设置成不可点
                    this._setAllBoxItemsClickEnable(false);

                    let resp = await cc.vv.gameData.reqSubGame({rtype:3, act:1, choices:[boxItem.getId()]});
                    if (resp.code === 200) {
                        let data = resp.data;
                        this._setSubGameData(data.freeBags);

                        //显示标题
                        this._setTitleType(TitleType.GOOD_LUCK);
                        //显示YourGift
                        await this._showYourBox(boxItem, true);
                        //下一步
                        success();
                    }
                    else {
                        AppLog.err("返回报错了");
                        //下一步
                        success();
                    }
                });
            }
        });
    },

    //显示YourGift
    _showYourBox (boxItem, bFly) {
        if (this._yourGiftBoxItem) {
            this._yourGiftBoxItem.node.removeFromParent();
            this._yourGiftBoxItem = null;
        }

        this._yourGiftBoxItem = new BoxItem(cc.instantiate(boxItem.node), this);
        this._yourGiftBoxItem.node.parent = this._uiBg2;
        this._yourGiftBoxItem.node.active = true;

        let startPos = this._cvtToLocalPos(boxItem.node, this._uiBg2);
        let targetPos = cc.find("box_pos", this._uiBg2).position;

        return new Promise(async (success)=>{
            if (bFly) {
                //消失选择的
                boxItem.playDisappear();
                //播放拖尾粒子效果
                this._yourGiftBoxItem.node.position = startPos;
                this._yourGiftBoxItem.flyToYourGift(startPos, targetPos);
                // this._yourGiftBoxItem.node.scale = 1.68;
                await this._awaitTime(2.0);
            }
            else {
                this._yourGiftBoxItem.node.position = targetPos;
                this._yourGiftBoxItem.node.scale = 1.68;
            }
            //bg2粒子显示
            let particle = cc.find("xiangshangParticle", this._uiBg2);
            particle.active = true;
            particle.getComponent(cc.ParticleSystem).resetSystem();

            success();
        });
    },

    _chooseCurRoundBox (chooseBoxNum) {
        let count = 0;

        return new Promise(async (success)=>{
            //全部设置成可点
            this._setAllBoxItemsClickEnable(true);

            for (let boxItem of this._boxItemsList) {
                boxItem.setClickCallback(async ()=>{
                    Global.SlotsSoundMgr.playEffect("click_deal");

                    //全部设置成不可点
                    this._setAllBoxItemsClickEnable(false);

                    if (boxItem.hasStrokeEff()) {
                        boxItem.removeStrokeEff();
                        count --;

                        await this._awaitTime(0.21);
                    }
                    else {
                        boxItem.playPinkStroke();
                        count ++;

                        await this._awaitTime(0.15);
                    }

                    //显示标题
                    this._setTitleType(TitleType.SELECT_TIMES, count);

                    //个数收集满
                    if (count == chooseBoxNum) {
                        this._setTitleType(TitleType.GOOD_LUCK);

                        //找到所有的下标
                        let idArr = [];
                        for (let tItem of this._boxItemsList) {
                            if (tItem.node.active && tItem.hasStrokeEff()) {
                                idArr.push(tItem.getId());
                            }
                        }
                        this._curRoundPickBoxList = idArr;

                        let resp = await cc.vv.gameData.reqSubGame({rtype:3, act:2, choices:idArr});
                        if (resp.code === 200) {
                            let data = resp.data;
                            if (data.spcode && data.spcode==967) {
                                cc.vv.FloatTip.show("流程错误！！！");
                                success();
                                return;
                            }
                            this._setSubGameData(data.freeBags);

                            await this._awaitTime(0.8);
                            //播放中奖特效
                            await this._playOpenRewardEff(idArr,data.items);
                            //下一步
                            success();
                        }
                        else {
                            AppLog.err("返回报错了");
                            //下一步
                            success();
                        }
                    }
                    else {
                        //全部设置成不可点
                        this._setAllBoxItemsClickEnable(true);
                    }
                });
            }
        });
    },

    //设置Title类型
    _setTitleType (type, count) {
        for (let i=1;i<=3; i++) cc.find("listBg/sprTitle" + i, this._uiMain).active = false;
        cc.find("listBg/sprTitle" + type, this._uiMain).active = true;
        if (type == TitleType.SELECT_TIMES) {
            this._setLabel(cc.find("listBg/lblCount", this._uiMain), this._nextChooseCount - count);
        }
        else {
            this._setLabel(cc.find("listBg/lblCount", this._uiMain), "");
        }
    },

    _setAllBoxItemsClickEnable (clickEnable) {
        for (let boxItem of this._boxItemsList) {
            if (boxItem.node.active) {
                boxItem.setClickEnable(clickEnable);
            }
            else {
                boxItem.setClickEnable(false);
            }
        }
    },

    _playCollecGiftBoxEff () {
        return new Promise(async (success)=>{
            this._boxItemsList[this._currCount - 1].playAppearEff();
            await this._awaitTime(1.0);

            success();
        });
    },

    //选中礼物---播放开启效果
    _playOpenRewardEff (idNumArr, multNumArr) {
        return new Promise(async (success)=>{
            //显示标题
            this._setTitleType(TitleType.GOOD_LUCK);

            let ui = cc.find("uiRewardEff", this.node);
            ui.active = true;

            let box = cc.find("box", ui);
            box.scale = 0;

            let lblIdNum = cc.find("lblIdxNum", box);

            let particle = cc.find("particle", ui);
            particle.active = false;

            let openBox = cc.find("openBox", ui);
            openBox.opacity = 255;

            let spine_light = cc.find("spine_light", openBox);
            spine_light.scale = 0;

            let spine_box = cc.find("spine_box", openBox);
            spine_box.active = false;

            let lblMult = cc.find("lblMult", openBox);
            lblMult.scale = 0;

            let spineBreak = cc.find("spine_break", openBox);
            spineBreak.active = false;

            this.scheduleOnce(()=>{
                particle.getComponent(cc.ParticleSystem).resetSystem();
            }, 0.5);

            Global.SlotsSoundMgr.playEffect("bonus_dialog2");

            for (let i in idNumArr) {
                let mult1 = multNumArr[i][0];
                let mult2 = mult1; //变化后的
                if (multNumArr[i].length > 1) {
                    mult2 = multNumArr[i][1];
                }

                this._setLabel(lblIdNum, idNumArr[i]);
                this._setLabel(lblMult, mult2 + "X");

                box.scale = 0;
                lblMult.scale = 0;
                spine_light.scale = 0;
                openBox.opacity = 255;
                spine_box.active = false;

                let boxItem = this._boxItemsList[idNumArr[i] - 1];
                if (boxItem.node.active) {
                    boxItem.playDisappear();
                }

                if (mult2 >= 1000) Global.SlotsSoundMgr.playEffect("1000_ohno");

                this._playActions(spine_light, [cc.scaleTo(0.5, 1.0)]);
                await this._playActions(box, [cc.scaleTo(0.4, 0.9), cc.scaleTo(0.2, 0.6)]);
                await this._awaitTime(0.6);
                box.scale=0;

                if (i == idNumArr.length - 1) { //最后礼盒打开
                    Global.SlotsSoundMgr.playEffect("gift_final");
                }
                else {
                    Global.SlotsSoundMgr.playEffect("gift_open");
                }

                await this._playSpine(spine_box, "animation1");
                await this._awaitTime(0.4);
                await this._playActions(lblMult, [cc.scaleTo(0.3, 1.4), cc.scaleTo(0.1, 1)]);
                if (mult1 != mult2) { //倍数变化
                    this.scheduleOnce(()=>{
                        this._setLabel(lblMult, mult1 + "X");
                        Global.SlotsSoundMgr.playEffect("1000X");
                    }, 2.0);

                    await this._playSpine(spineBreak, "animation", false, ()=>{
                        spineBreak = false;
                    });
                }

                let idx = this._getIdxByMult(mult1);
                if(idx) this._multItemsList[idx].playToGray();
                await this._awaitTime(0.8);
                await this._playActions(openBox, [cc.fadeTo(0.5, 0)]);
                await this._awaitTime(0.8);
            }

            await this._awaitTime(0.2);
            ui.active = false;

            success();
        });
    },

    //显示模式
    //收集模式，游戏模式
    _showModule (isCollecting) {
        let hasChange = (this._uiBg1.active != isCollecting);

        if (isCollecting) {
            this._uiBg1.active = true;

            if (hasChange) {
                this._uiBg2.opacity = 255;
                cc.tween(this._uiBg2)
                    .to(0.4, {opacity:0})
                    .call(()=>{
                        this._uiBg2.active = false;
                    })
                    .start();
            }
            else {
                this._uiBg2.active = false;
            }
        }
        else {
            this._uiBg1.active = false;
            this._uiBg2.active = true;

            if (hasChange) {
                this._uiBg2.opacity = 0;
                cc.tween(this._uiBg2)
                    .to(0.4, {opacity:255})
                    .start();
            }
        }
    },

    //弹出UI--开始
    async popUIStartTips () {
        return new Promise(async (success)=>{
            let tips = cc.find("uiStartTips", this.node);
            tips.active = true;

            let ui = cc.find("ui", tips);
            ui.scale = 0;

            let btn = ui.getChildByName("btnStart");
            btn.getComponent(cc.Button).enabled = false;

            Global.SlotsSoundMgr.playEffect("bonus_dialog1");
            await this._playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            //显示标题
            this._setTitleType(TitleType.CHOOSE_GIFT);

            btn.getComponent(cc.Button).enabled = true;
            btn.off("click");

            let func = async ()=>{
                btn.getComponent(cc.Button).enabled = false;
                await this._playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);
                tips.active = false;
                success();
            }

            cc.vv.gameData.checkAutoPlay(btn, func);

            Global.btnClickEvent(btn, async ()=>{
                btn.stopAllActions();
                await func();
            },this);
        });
    },

    //弹出UI--Round
    async popUIRoundTips (roundNum, pickNum) {
        return new Promise(async (success)=>{
            let tips = cc.find("uiRoundTips", this.node);
            tips.active = true;

            let ui = tips.getChildByName("ui");
            ui.scale = 0;

            let normal = cc.find("noraml", ui);
            let lastChance = cc.find("lastChance", ui);
            if (roundNum == this._totalRound) { //最后一轮
                normal.active = false;
                lastChance.active = true;
            }
            else {
                normal.active = true;
                lastChance.active = false;
                this._setLabel(cc.find("noraml/lblRound", ui), roundNum);
                this._setLabel(cc.find("noraml/lblPickNum", ui), pickNum);
            }

            await this._playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);
            await this._awaitTime(1.0);
            Global.SlotsSoundMgr.playEffect("change");
            await this._playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);


            tips.active = false;

            success();
        });
    },

    //弹出UI--Round结果
    async popUIRoundResultTips () {
        return new Promise(async (success)=>{
            let tips = cc.find("uiRoundResultTips", this.node);
            tips.active = true;

            let btn = tips.getChildByName("btnLetter");
            btn.zIndex = 2;
            btn.getComponent(cc.Button).enabled = false;

            let ui = tips.getChildByName("ui");
            ui.zIndex = 1;
            ui.active = false;
            ui.y = -185;


            this._setLabel(ui.getChildByName("lblMult"), this._gainMult + "X");
            let desc = Global.convertNumToShort(this._prize) +  " X " + this._gainMult + " = " + Global.convertNumToShort(this._prize*this._gainMult);
            this._setLabel(ui.getChildByName("lblContent"), desc);

            //信封
            tips.getChildByName("spine_btm").active = false;
            tips.getChildByName("spine").zIndex = 2;

            Global.SlotsSoundMgr.playEffect("envelope");
            await this._playSpine(tips.getChildByName("spine"), "animation1");
            //提示操作
            Global.SlotsSoundMgr.playEffect("envelope_intro");
            this._playSpine(tips.getChildByName("spine"), "animation2", true);

            btn.getComponent(cc.Button).enabled = true;

            btn.off("click");

            let func = async ()=>{
                btn.getComponent(cc.Button).enabled = false;

                //信封准备打开
                Global.SlotsSoundMgr.playEffect("envelope_open");
                await this._playSpine(tips.getChildByName("spine"), "animation3");

                //显示UI
                ui.active = true;
                ui.scale = 1.0;
                ui.angle = -18;

                //打开信封
                this._playSpine(tips.getChildByName("spine"), "animation4");
                // await this._awaitTime(0.3);
                this._playSpine(tips.getChildByName("spine_btm"), "animation5");
                await this._awaitTime(1.5);

                //ui出现
                await this._playActions(ui, [cc.moveTo(0.3, cc.v2(ui.x, 200)),
                    cc.callFunc(()=>{
                        ui.zIndex = 3;
                    }),
                    cc.spawn(cc.moveTo(0.3, cc.v2(ui.x, -185)), cc.scaleTo(0.3, 1.5), cc.rotateTo(0.3, 0)),
                ]);
                Global.SlotsSoundMgr.playEffect("envelope_out");

                let btnTake = ui.getChildByName("btnTakeIt");
                btnTake.off("click");
                btnTake.getComponent(cc.Button).enabled = true;
                Global.btnClickEvent(btnTake, async ()=> {
                    btnTake.getComponent(cc.Button).enabled = false;

                    let resp = await cc.vv.gameData.reqSubGame({rtype:3, act:3, takeIt:true});
                    if (resp.code === 200) {
                        let data = resp.data;
                        data.freeBags.winCoin = data.winCoin;
                        data.freeBags.mult = data.mult;
                        data.freeBags.prize = data.prize;
                        this._setSubGameData(data.freeBags);

                        //下一步
                        success(true);
                    }
                    else {
                        AppLog.err("返回报错了");
                        //下一步
                        success();
                    }

                    tips.active = false;
                    success();
                },this);

                let btnLeave = ui.getChildByName("btnLeaveIt");
                btnLeave.off("click");
                btnLeave.getComponent(cc.Button).enabled = true;
                Global.btnClickEvent(btnLeave, async ()=>  {
                    btnLeave.getComponent(cc.Button).enabled = false;

                    let resp = await cc.vv.gameData.reqSubGame({rtype:3, act:3, takeIt:false});
                    if (resp.code === 200) {
                        let data = resp.data;
                        this._setSubGameData(data.freeBags);

                        //显示已放弃倍数
                        for (let i in this._historyMult) {
                            this._setLabel(this._giveMultLblList[i], this._historyMult[i]+"X");
                        }

                        //下一步
                        success(false);
                    }
                    else {
                        AppLog.err("返回报错了");
                        //下一步
                        success();
                    }

                    tips.active = false;
                    success();
                },this);

            };

            cc.vv.gameData.checkAutoPlay(btn, func);

            Global.btnClickEvent(btn, async ()=> {
                btn.stopAllActions();
                await func();
            },this);
        });
    },

    //弹出UI--最后Round选择
    async popUILastRoundSelectTip (keepId, tradeId) {
        return new Promise(async (success)=>{
            let tips = cc.find("uiLastRoundSelectTips", this.node);
            tips.active = true;

            let ui = tips.getChildByName("ui");
            ui.scale = 0;

            cc.find("Item1", ui).active = true;
            this._setLabel(cc.find("Item1/lblIdxNum", ui), keepId);
            cc.find("Item2", ui).active = true;
            this._setLabel(cc.find("Item2/lblIdxNum", ui), tradeId);

            let btnKeep = ui.getChildByName("btnKeep");
            btnKeep.getComponent(cc.Button).enabled = false;

            let btnTrade = ui.getChildByName("btnTrade");
            btnTrade.getComponent(cc.Button).enabled = false;

            Global.SlotsSoundMgr.playEffect("deal_scene_open");
            await this._playActions(ui, [cc.scaleTo(0.3, 1.8), cc.scaleTo(0.1, 1.5)]);

            let endCall1 = function()  {
                btnKeep.getComponent(cc.Button).enabled = false;
                btnTrade.getComponent(cc.Button).enabled = false;
            };

            let endCall2 = async () => {
                await this._playActions(ui, [cc.scaleTo(0.1, 1.8), cc.scaleTo(0.3, 0)]);
                tips.active = false;
                success();
            };

            btnKeep.getComponent(cc.Button).enabled = true;
            btnKeep.off("click");
            Global.btnClickEvent(btnKeep, async ()=> {
                //按钮不可点
                endCall1();

                let resp = await cc.vv.gameData.reqSubGame({rtype:3, act:4, keep:true});
                if (resp.code === 200) {
                    let data = resp.data;
                    data.freeBags.winCoin = data.winCoin;
                    data.freeBags.mult = data.mult;
                    data.freeBags.prize = data.prize;
                    this._setSubGameData(data.freeBags);

                    cc.find("Item1", ui).active = false;
                    //显示获奖
                    await this._playOpenRewardEff([keepId],[[data.mult]]);

                    //下一步
                    success(false);
                }
                else {
                    AppLog.err("返回报错了");
                    //下一步
                    success();
                }

                //消失
                endCall2();
            });

            btnTrade.getComponent(cc.Button).enabled = true;
            btnTrade.off("click");
            Global.btnClickEvent(btnTrade, async ()=> {
                //按钮不可点
                endCall1();

                let resp = await cc.vv.gameData.reqSubGame({rtype:3, act:4, keep:false});
                if (resp.code === 200) {
                    let data = resp.data;
                    data.freeBags.winCoin = data.winCoin;
                    data.freeBags.mult = data.mult;
                    data.freeBags.prize = data.prize;
                    this._setSubGameData(data.freeBags);

                    cc.find("Item2", ui).active = false;
                    //显示获奖
                    await this._playOpenRewardEff([tradeId],[[data.mult]]);

                    //下一步
                    success(false);
                }
                else {
                    AppLog.err("返回报错了");
                    //下一步
                    success();
                }

                //消失
                endCall2();
            });

        });
    },

    //弹出UI--总的结果结束也没
    async popUIEndResultTips () {
        return new Promise(async (success)=>{
            let tips = cc.find("uiResultDialuage", this.node);
            tips.active = true;

            let ui = tips.getChildByName("ui");
            ui.scale = 0;

            this._setLabel(ui.getChildByName("lblCoinNum"), Global.FormatNumToComma(this._freeBags.winCoin));
            let desc = this._gainMult + " X " + Global.convertNumToShort(this._prize) +  " = " + Global.convertNumToShort(this._freeBags.winCoin);
            this._setLabel(ui.getChildByName("lblContent"), desc);

            let btn = ui.getChildByName("btnCollect");
            btn.getComponent(cc.Button).enabled = false;

            Global.SlotsSoundMgr.playEffect("multipler");
            await this._playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            btn.getComponent(cc.Button).enabled = true;
            btn.off("click");

            let func = async ()=>{
                btn.getComponent(cc.Button).enabled = false;
                await this._playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);

                tips.active = false;
                success();
            }

            cc.vv.gameData.checkAutoPlay(btn, func);

            Global.btnClickEvent(btn, async ()=>{
                btn.stopAllActions();
                await func();
            });
        });
    },

    _setSubGameData (freeBags) {
        if (freeBags) {
            this._freeBags = freeBags;
            //初始化数据
            this._initData();
        }
    },

    //隐现
    _appearFadeIn () {
        return new Promise((success)=>{
            this.node.active = true;
            this.node.opacity = 0;
            cc.tween(this.node)
                .to(0.3, {opacity:255})
                .call(()=>{
                    success();
                })
                .start();
        });
    },

    //隐退
    _disappearFadeOut () {
        return new Promise((success)=>{
            this.node.active = true;
            this.node.opacity = 255;
            cc.tween(this.node)
                .to(0.3, {opacity:0})
                .call(()=>{
                    this.node.active = false;
                    success();
                })
                .start();
        });
    },

    //播放Spine
    _playSpine (node, animationName="animation", isLoop=false, endCall=null) {
        return new Promise((success)=>{
            if (node) {
                node.active = true;
                console.log("播放节点[" + node.parent.name + "/" + node.name + "]的spine动作: " + animationName);
                node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
                if (!isLoop) {
                    node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                        if (endCall) endCall();
                        success(); //下一步
                    });
                }
                else {
                    success(); //下一步
                }
            }
            else {
                if (endCall) endCall();
                success(); //下一步
            }
        });
    },

    //播放Actions
    _playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },

    //等待时间
    _awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },

    _setLabel (lblNode, str) {
        if (lblNode) {
            lblNode.getComponent(cc.Label).string = str;
        }
    },

    _cvtToLocalPos (node, localNode) {
        return localNode.convertToNodeSpaceAR(node.parent.convertToWorldSpaceAR(node.position));
    },
});
