cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _enable:false,
        _restSpinTimes: 0,

        _goldenNum: 0,

        _top_star_symbols: null,
        _star_top_anim: null,
    },

    onLoad () {
        this._super();

        this._top_star_symbols = [];
        this._star_top_anim = cc.find("star_top_ani", this.node);

        this._spine_addCoin = cc.find("spine_addCoin", this._star_top_anim);
        this._spine_addCoin.active = false;
        this._spine_addCoin.zIndex = 800;

        Global.StarBonusRespin = this;
    },
    onDestroy() {
        Global.StarBonusRespin = null;
    },

    //断线重连的显示
    //可根据自己断线逻辑重写
    ReconnectShow:function() {
        if (cc.vv.gameData.getDeskInfo().coinBonus && cc.vv.gameData.getDeskInfo().coinBonus.state) {
            this._bottomScript.ShowBtnsByState("moveing_1")
            this.showRespin(true, true);

            this._restSpinTimes = cc.vv.gameData.getDeskInfo().coinBonus.num || 5;
            this.setRestSpinTimes(this._restSpinTimes);
        }
        else {
            this.showRespin(false, true);
        }
    },

    //重写
    //点击旋转按钮调用
    StartMove:function() {
        Global.SlotsSoundMgr.playEffect("remaining");

        this.setRestSpinTimes(this._restSpinTimes -1);
        this._super();

        for (let reel of this._reels) {
            reel.SetSpeed(2500);
        }
    },

    //初始化
    Init:function(){
        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()

        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = 15; //Changed by andy
        this._row = 1; //Changed by andy

        this.createReels(this._col,this._row)

        // this._bottomScript.ShowBtnsByState("idle")

        this.RegisterEvent()

        //断线重连的显示
        this.ReconnectShow()
    },

    bEnable () {
        return this._enable;
    },

    //游戏被选择
    async onSelected () {
        let resp = await cc.vv.gameData.reqSubGame({rtype:2, idx:1});
        if (resp.code === 200) {
            let data = resp.data;

            let gameInfo = cc.vv.gameData.getGameInfo() || cc.vv.gameData.getDeskInfo();
            gameInfo.coinBonus = data;

            cc.vv.gameData.SetFreeTime(0);
            cc.vv.gameData.SetTotalFree(0);

            this._bottomScript.ShowBtnsByState("moveing_1");
            await SlotsFacade.popup.showTransition2();
            this.showRespin(true);
            SlotsFacade.character.hide();
        }
        else {
            AppLog.err("返回报错了");
        }
    },

    setRestSpinTimes (timesNum) {
        cc.vv.gameData.SetRespinTime(timesNum);

        let tips = cc.find("respin_bg/respinTipsBg/tips", this.node);
        let atlas = cc.vv.gameData.GetAtlasByName("bonus");
        if (timesNum > 1) {
            tips.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme129_remaining_text6");
        }
        else if (timesNum == 1) {
            tips.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme129_remaining_text5");
        }
        else if (timesNum == 0) {
            tips.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme129_remaining_text1");
        }
        else { //表示已经完成
            tips.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme129_remaining_text2");
        }

        let lblTimes = cc.find("respin_bg/respinTipsBg/lbTimes", this.node);
        this._setLabel(lblTimes, timesNum>0?timesNum:"");
    },
    
    setStarsNum (timesNum) {
        let lblTimes = cc.find("respin_bg/nodeCenter/lblRespinTimes", this.node);
        this._setLabel(lblTimes, timesNum>0?timesNum:"");
    },

    setEachSilveryStarWinsCoin (coinNum) {
        let lblWinCoin = cc.find("respin_bg/item1/lblWinCoin", this.node);
        this._setLabel(lblWinCoin, Global.convertNumToShort(coinNum, null, 2));
    },

    setEachGoldStarWinsCoin (coinNum) {
        let lblWinCoin = cc.find("respin_bg/item2/lblWinCoin", this.node);
        let grand = cc.find("respin_bg/item2/grand", this.node);

        if (coinNum) {
            this._goldenNum = coinNum;

            lblWinCoin.active = true;
            this._setLabel(lblWinCoin, Global.convertNumToShort(coinNum, null, 2));

            grand.active = false;
        }
        else {
            lblWinCoin.active = false;
            grand.active = true;
        }
    },

    getIdByType (type) {
        switch (type) {
            case 1:
                return 2; //铜星星
            case 2:
                return 14; //白银星星
            case 3:
                return 15; //黄金星星
            case 4:
                return 16; //spin+1
        }
    },

    showRespin (bShow, bReconnect = false) {
        this._enable = bShow;

        let refreshShow = ()=>{
            this.node.active = bShow;
            for (let node of this.node.children) node.active = bShow;
        }

        if (bShow) {
            Global.SlotsSoundMgr.playBgm("respin_bgm");

            //先显示
            refreshShow();

            //需要服务端给数据
            // cc.find("respin_bg/prizePool_Grand", this.node).getComponent("LMSlotMachine_PrizePool").PausePrizePool(12313);

            cc.find("respin_bg/nodeCenter", this.node).active = true;
            cc.find("respin_bg/winnerBg", this.node).active = false;
            this._setLabel(cc.find("respin_bg/winnerBg/lblWinCoin", this.node), "");
            cc.find("uiPopGrand", this.node).active = false;

            let coinBonus = cc.vv.gameData.getGameInfo()?cc.vv.gameData.getGameInfo().coinBonus:cc.vv.gameData.getDeskInfo().coinBonus;

            let slotScript = cc.vv.gameData.GetSlotsScript();
            for (let i=1; i<=15; i++) {
                if (coinBonus) {
                    let newSymbol = this.GetSymbolByIdx(i);
                    if (coinBonus.info && coinBonus.info["idx_" + i]) {
                        let id = this.getIdByType(coinBonus.info["idx_" + i].type);
                        let data = {t:"coin", type:coinBonus.info["idx_" + i].type, num: coinBonus.info["idx_" + i].num};
                        newSymbol.ShowById(id, data, false);
                        newSymbol.SetCoinNum(Global.convertNumToShort(data.num));
                        this.setSymbolToTop(newSymbol, i - 1, false, data);
                    }
                    else {
                        let id = slotScript.GetSymbolByIdx(i).GetShowId();
                        let data = Global.copy(slotScript.GetSymbolByIdx(i).GetData());
                        newSymbol.ShowById(id, data);
                    }
                }
            }

            //刷新星星数
            let starNum = 0;
            for (let i in coinBonus.info) starNum ++;
            this.setStarsNum(starNum);

            //设置当前Slots
            cc.vv.gameData.SetSlotsScript(this);

            this._restSpinTimes = coinBonus.num || 5;
            this.setRestSpinTimes(this._restSpinTimes);

            this.setEachSilveryStarWinsCoin(coinBonus.silvery);
            this.setEachGoldStarWinsCoin(coinBonus.golden);

            //开始旋转
            this.scheduleOnce(()=>{
                this.CanDoNextRound();
            }, 1.0);
        }
        else {
            this.removeAllSymbolOfTop();

            let cfg = cc.vv.gameData.getGameCfg()
            let node_slots = cc.find('slots',this.node.parent);
            let script_slots = node_slots.getComponent(cfg.scripts.Slots);
            cc.vv.gameData.SetSlotsScript(script_slots);

            //后隐藏
            refreshShow();

            if(!bReconnect){
                this._bottomScript.ShowBtnsByState("idle");
            }
        }
    },

    //显示结算界面
    async showGrand(winCoin) {
        let uiPopGrand = cc.find("uiPopGrand", this.node);

        //更新winCoin
        let twinCoin = winCoin;
        let winCoinStr = Global.formatMoney(twinCoin);
        let num = 0;
        while (winCoinStr.length > 10) {
            twinCoin = Math.floor(twinCoin/1000);
            winCoinStr = Global.formatMoney(twinCoin);
            num ++;
        }
        let unit = ["", "K", "M", "B", "T", "Q"];
        winCoinStr += unit[num];

        let lblWinCoin = cc.find("lblWinCoin", uiPopGrand).getComponent(cc.Label);
        lblWinCoin.string = winCoinStr;

        Global.SlotsSoundMgr.playEffect("grand");

        //出现效果
        uiPopGrand.active = true;
        uiPopGrand.opacity = 0;
        await this._playActions(uiPopGrand, [cc.fadeIn(0.5)]);
        await this._awaitTime(2.0);
        await this._playActions(uiPopGrand, [cc.fadeOut(0.2)]);
        uiPopGrand.active = false;
    },

    //每列停止时间间隔 = 每列的停止间隔 + 每列的回弹时间
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        return (reelIdx%5)*0.2;
    },

    //单列停止
    //colIdx:0开始
    //回弹动作执行之前的停止时机
    OnReelSpinEnd:function(colIdx){
        this._super();

        let reel = this._reels[colIdx];
        let symbol = reel.GetSymbolByRow(0);
        if (symbol.GetShowId() == 14 || symbol.GetShowId() == 15 ) { //|| symbol.GetShowId() == 16) {
            this.setSymbolToTop(symbol, colIdx, true);
        }
    },

    //实际旋转起来的列，有时候需要1，2，4列转，
    //即最后停止下来的不是最后一列的序号，所以需要记录最后一列的序号
    //arry=[this._reels[0],this._reels[1],this._reels[4]]
    MoveReels:function(arry){
        this.moveReelLastIdx = -1;
        let virtualCol = -1;
        for(let i = 0; i < arry.length; i++){
            let item = arry[i];
            if (item.node.active) {
                item.StartMove()
                let idx = item.GetReelIdx();
                let col = idx%5;

                if(idx> this.moveReelLastIdx && col > virtualCol){
                    this.moveReelLastIdx = idx
                    virtualCol = col;
                }
            }
        }
    },

    setSymbolToTop (symbol, idx, isNew=false, data) {
        if (this._top_star_symbols[idx]) return;

        let symbolNode = cc.instantiate(symbol.node);
        let wordPos = symbol.node.convertToWorldSpaceAR(cc.v2(0.0));
        symbolNode.parent = this._star_top_anim;
        symbolNode.position = this._star_top_anim.convertToNodeSpaceAR(wordPos);
        symbolNode.zIndex = 100+idx;
        this._top_star_symbols[idx] = symbolNode;

        //设置显示图片，且未完整图片
        let cfg = cc.vv.gameData.getGameCfg();
        let symbolNodeScript = symbolNode.getComponent(cfg.scripts.Symbols);
        symbolNodeScript.ShowById(symbol.GetShowId(), symbol.GetData(), false);
        if(data){
            symbolNodeScript.SetCoinNum(Global.convertNumToShort(data.num));
        }
        symbolNodeScript._isNew = isNew; //设置来区分是否是本局新增的

        //隐藏掉reel
        this._reels[idx].node.active = false;
    },

    removeAllSymbolOfTop () {
        for (let i in this._top_star_symbols) {
            if (this._top_star_symbols[i]) {
                this._top_star_symbols[i].removeFromParent();
                this._top_star_symbols[i] = null;
            }
        }
        this._top_star_symbols = [];

        for (let reel of this._reels) {
            reel.node.active = true;
        }
    },


    playStarAddCoin (newStarSymbol) {
        return new Promise(async (success)=>{
            let cfg = cc.vv.gameData.getGameCfg();

            let totalCoin = 0;
            for (let col=0; col<5; col++) {
                for (let i in this._top_star_symbols) {
                    if (parseInt(i)%5 != col) continue;

                    let oldSymbol = this._top_star_symbols[i].getComponent(cfg.scripts.Symbols);
                    if (oldSymbol._isNew) continue; //本局新增 不需要增加金币

                    if (oldSymbol.GetShowId() > newStarSymbol.GetShowId()) continue; //黄金的不需要给银色的添加
                    if (oldSymbol.GetShowId() == newStarSymbol.GetShowId() && oldSymbol.GetShowId() == 14) continue; //银色的不需要给银色的添加

                    totalCoin += oldSymbol.GetCoinNum() || 0;

                    this._spine_addCoin.position = oldSymbol.node.position;
                    this._spine_addCoin.active = true;

                    let targetPos = newStarSymbol.node.position;

                    this._playSpine(this._spine_addCoin, "animation1");

                    Global.SlotsSoundMgr.playEffect("light_circle1");

                    this._spine_addCoin.stopAllActions();
                    await this._playActions(this._spine_addCoin, [
                        cc.delayTime(0.1),
                        cc.moveTo(0.5, targetPos),
                        cc.callFunc(()=>{
                            newStarSymbol.playAppearAnimation(false);
                            newStarSymbol.SetCoinNum(Global.convertNumToShort(totalCoin));

                            Global.SlotsSoundMgr.playEffect("add");
                        }),
                    ]);
                }
            }

            Global.SlotsSoundMgr.playEffect("light_circle2");
            this.setEachGoldStarWinsCoin(this._goldenNum + totalCoin);

            newStarSymbol._data = {t:"coin", num:totalCoin};
            newStarSymbol._isNew = false; //需要增加金币

            success();
        });
    },

    showResult () {
        return new Promise(async (success)=>{
            cc.find("respin_bg/nodeCenter", this.node).active = false;

            let winnerBg = cc.find("respin_bg/winnerBg", this.node);
            winnerBg.active = true;

            //播放闪光
            for (let i in this._top_star_symbols) {
                let symbolNode = this._top_star_symbols[i];
                this._playSpine(cc.find("w_guang", symbolNode), "animation2", true);
            }

            await this._awaitTime(1.0);

            //播放飞到奖池
            let totalCoin = this._top_star_symbols.length==15?cc.vv.gameData.getGameInfo().jackpot:0;
            let cfg = cc.vv.gameData.getGameCfg();
            for (let col=0; col<5; col++) {
                for (let i in this._top_star_symbols) {
                    if (parseInt(i)%5 != col) continue;

                    let symbolNode = this._top_star_symbols[i];

                    let spineNode = cc.find("w_guang", symbolNode);
                    this._playSpine(spineNode, "animation3");

                    spineNode.stopAllActions();
                    await this._playActions(spineNode, [
                        cc.delayTime(0.1),
                        cc.moveTo(0.6, spineNode.convertToNodeSpaceAR(winnerBg.convertToWorldSpaceAR(cc.v2(0, 0)))),
                        cc.callFunc(() => {
                            totalCoin += symbolNode.getComponent(cfg.scripts.Symbols).GetCoinNum();
                            this._setLabel(cc.find("lblWinCoin", winnerBg), Global.formatMoney(totalCoin));
                            this._playSpine(cc.find("spine_frame", winnerBg));

                            this._bottomScript.SetWin(totalCoin);

                            Global.SlotsSoundMgr.playEffect("collect");
                        }),
                        cc.delayTime(0.1),
                    ]);
                }
            }

            success();
        });
    },

    //如果收到结果不需要里面进入停止节奏，可通过重写此接口来实现自己控制
    //默认是收到结果就停止
    update (dt) {
        this._super(dt);

        if(this.CanStopSlot()){//满足开始停止的条件
            this._bottomScript.ShowBtnsByState("moveing_1");
        }
    },

    //收到旋转结果
    //gameData模块收到数据后，转发到此处
    onMsgSpine:function(msg){
       this._super(msg);

       //去掉停止音效
       for (let reel of this._reels) {
           for (let info of reel._reelState) {
               info.reelStopSound = '';
           }
       }
    },

    //重写：显示bonus中奖
    async OnSpinEnd () {
        let cfg = cc.vv.gameData.getGameCfg();

        let coinBonus = cc.vv.gameData.getGameInfo().coinBonus;
        this._restSpinTimes = coinBonus.num;

        //刷新星星数
        let starNum = 0;
        for (let i in coinBonus.info) if (coinBonus.info[i] && coinBonus.info[i].type) starNum ++;
        this.setStarsNum(starNum);

        //相关特效表现 todo ...
        if (coinBonus.addItems && coinBonus.addItems.length > 0) {
            for (let idx of coinBonus.addItems) {
                let info = coinBonus.info["idx_" + idx];
                if (info) {
                    if (info.type == 4) {
                        // this._restSpinTimes += 1;
                        this.setRestSpinTimes(this._restSpinTimes);
                    }
                    else {
                        if (this._top_star_symbols[idx - 1]) {
                            await this.playStarAddCoin(this._top_star_symbols[idx - 1].getComponent(cfg.scripts.Symbols));
                        }
                    }
                }
            }
            this.setEachGoldStarWinsCoin(coinBonus.golden); //刷新金星星显示
        }

        await this._awaitTime(1.0);

        if (this._restSpinTimes <= 0 || (cc.vv.gameData.getGameInfo().jackpot && cc.vv.gameData.getGameInfo().jackpot > 0)) {
            this.setRestSpinTimes(-1);
            Global.SlotsSoundMgr.playEffect("spin_end");

            if (cc.vv.gameData.getGameInfo().jackpot && cc.vv.gameData.getGameInfo().jackpot > 0) {
                await this.showGrand(cc.vv.gameData.getGameInfo().jackpot);
            }

            await this.showResult();
            let winCoin = Global.FormatCommaNumToNum(cc.find("respin_bg/winnerBg/lblWinCoin", this.node).getComponent(cc.Label).string);
            await SlotsFacade.popup.showFreegameResultDialog(false, winCoin);
            await this.playBottomWin(winCoin);

            await SlotsFacade.popup.showTransition2();
            this.showRespin(false);
            Global.SlotsSoundMgr.stopBgm();
            SlotsFacade.character.show();

            await cc.vv.gameData.awaitTime(0.3);
        }

        //下一局
        this.CanDoNextRound();
    },

    async playBottomWin (winCoin) {
        return new Promise(async (success)=>{
            let nWin = winCoin;
            let nTotal = winCoin;
            let updateAllCoin = true;
            if (nWin > 0) {
                await this.ShowBottomWin(nWin,nTotal,updateAllCoin, ()=>{
                    success();
                });
            }
            else {
                success();
            }
        });
    },

    //播放Spine
    _playSpine (node, animationName="animation", isLoop=false, endCall=null) {
        return new Promise((success)=>{
            if (node) {
                node.active = true;
                console.log("播放节点[" + node.parent.name + "/" + node.name + "]的spine动作: " + animationName);
                node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
                if (!isLoop) {
                    node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                        if (endCall) endCall();
                        success(); //下一步
                    });
                }
                else {
                    success(); //下一步
                }
            }
            else {
                if (endCall) endCall();
                success(); //下一步
            }
        });
    },

    //播放Actions
    _playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },

    //等待时间
    _awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },

    _setLabel (lblNode, str) {
        if (lblNode) {
            lblNode.getComponent(cc.Label).string = str;
        }
    },

    _cvtToLocalPos (node, localNode) {
        return localNode.convertToNodeSpaceAR(node.parent.convertToWorldSpaceAR(node.position));
    },
});
