cc.Class({
    extends: cc.Component,

    properties: {
        _spine_wildFly: null, //wild飞效果
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._spine_wildFly = cc.find("spine_wildFly", this.node);
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     * @param boolean isTrigger 是否触发收集游戏
     */
    async collectWild(globalPosArr, isTrigger) {
        if (globalPosArr.length <= 0) return;

        Global.SlotsSoundMgr.playEffect("wild_fly");

        let endPos = this.node.convertToNodeSpaceAR(SlotsFacade.character.getGiftPos());
        globalPosArr.forEach(v=>{
            let pos = this.node.convertToNodeSpaceAR(v);
            let spine_wild = cc.instantiate(this._spine_wildFly);
            spine_wild.parent = this.node;
            spine_wild.position = pos;
            spine_wild.active = true;

            cc.tween(spine_wild)
                .call(()=>{ //播放符号高亮效果
                    spine_wild.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                })
                .delay(0.2)
                .call(()=> { //播放飞的效果
                    spine_wild.getComponent(sp.Skeleton).setAnimation(0, "animation1_1", false);
                })
                .to(0.5, {position:endPos})
                .call(()=> { //播放飞的效果
                    spine_wild.removeFromParent();
                })
                .start();
        });
        await SlotsFacade.delayTime(0.7);
        SlotsFacade.character.playCollectGiftEffect();
        await SlotsFacade.delayTime(0.4);

        if (isTrigger) {
            Global.SlotsSoundMgr.playEffect("tree");
        }
        // this._spine_tree.getComponent(sp.Skeleton).setAnimation(0, isTrigger?"animation3":"animation2", false);
        // this._spine_tree.getComponent(sp.Skeleton).setCompleteListener(()=>{
        //     this._spine_tree.getComponent(sp.Skeleton).setAnimation(0, "animation1", true);
        //     this._spine_tree.getComponent(sp.Skeleton).setCompleteListener(null);
        // });

        await this.awaitTime(isTrigger?1.3:0.5);
    },

    //等待时间
    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },

});
